{
    "group": "Custom ExecutionContext configuration",
    "cases": [
        {
            "input": [
                {
                    "parameter": "executionContext",
                    "value": "new ExecutionContext().setFailFast(true)"
                },
                {
                    "parameter": "node",
                    "value": "objectNode({\"age\":30})"
                },
                {
                    "parameter": "validate",
                    "value": "true"
                }
            ],
            "expected": "ValidationResult.failure() – contains a single message about missing required property 'name' and stops after first error because failFast is true",
            "description": "When the ExecutionContext is configured with failFast, walk should abort after the first validation error instead of collecting all possible errors."
        },
        {
            "input": [
                {
                    "parameter": "executionContext",
                    "value": "new ExecutionContext().setCollectAnnotations(true)"
                },
                {
                    "parameter": "node",
                    "value": "objectNode({\"name\":\"John\"})"
                },
                {
                    "parameter": "validate",
                    "value": "true"
                }
            ],
            "expected": "ValidationResult.success() – includes annotation messages (e.g., \"default applied\") if schema defines defaults",
            "description": "When the ExecutionContext is set to collect annotations, walk should still succeed but the resulting ValidationResult must contain annotation messages generated by the validator."
        }
    ]
}
